const brl = (v) => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const b = $input.first().json.body || {};
const cfg = $('Config').first().json;
if (!cfg.token || b.token !== cfg.token) throw new Error('Token inválido');
const p = b.pedido;
if (!p || !p.id || !p.cliente_telefone) return [];
const lista = (p.itens || []).map((i) =>
  `• ${i.qtd}× ${i.nome}${i.detalhe ? ' (' + i.detalhe + ')' : ''}${i.obs ? ' · obs: ' + i.obs : ''} — ${brl(i.preco)}`).join('\n');
const pagto = {
  pix: 'Pix (aguardando comprovante)',
  cartao: p.tipo === 'entrega' ? 'Cartão na entrega' : 'Cartão',
  dinheiro: 'Dinheiro' + (p.troco_para ? ` (troco para ${brl(p.troco_para)})` : ''),
}[p.pagamento] || 'A combinar';
const recebe = p.tipo === 'entrega' ? `Entrega: ${p.endereco}` : 'Retirada no balcão';
const saida = [];

if (p.origem === 'site' && cfg.numero_loja) {
  saida.push({ numero: cfg.numero_loja, texto:
    `*NOVO PEDIDO PELO SITE #${p.id}*\nCliente: ${p.cliente_nome} (${p.cliente_telefone})\n${recebe}\n\n${lista}\n\n` +
    (p.observacoes ? `Obs.: ${p.observacoes}\n\n` : '') +
    `*Total: ${brl(p.total)}*\nPagamento: ${pagto}\n\nConfirme no painel de pedidos.` });
}

let cli = `Olá, ${p.cliente_nome}! Recebemos seu pedido *#${p.id}* na Naturalle Mania.\n\n${lista}\n\n`;
if (Number(p.taxa_entrega)) cli += `Taxa de entrega: ${brl(p.taxa_entrega)}\n`;
if (Number(p.acrescimo_cartao)) cli += `Acréscimo da maquininha: ${brl(p.acrescimo_cartao)}\n`;
cli += `*Total: ${brl(p.total)}*\n${recebe}\n\n`;
if (p.pagamento === 'pix') {
  cli += `Para pagar via Pix, use a chave:\n*${cfg.pix_chave}*\n(${cfg.pix_nome})\n\nDepois é só responder aqui com a foto do comprovante.`;
} else if (p.pagamento === 'cartao') {
  cli += p.tipo === 'entrega' ? 'Pagamento no cartão na entrega: o entregador leva a maquininha.' : 'Pagamento no cartão na retirada.';
} else if (p.pagamento === 'dinheiro') {
  cli += 'Pagamento em dinheiro' + (p.troco_para ? `, troco para ${brl(p.troco_para)}.` : '.');
}
cli += p.status === 'novo' ? '\n\nJá já confirmamos e avisamos por aqui!' : '\n\nJá está sendo preparado. Avisamos por aqui a cada etapa!';
saida.push({ numero: p.cliente_telefone, texto: cli });

return saida.map((json) => ({ json }));
